				if err != nil {
					return nil, fmt.Errorf("invalid color for %s: %w", name, err)
				}
				theme.colorsGeneric[fyne.ThemeColorName(name)] = c
			}
		}
	}

	// Parse colors-dark
	if colorsRaw, ok := raw["colors-dark"].(map[string]interface{}); ok {
		for name, value := range colorsRaw {
